package com.bank.latency;

// Saturated pool adds wait time even though CPU is idle (threads just park).
public class ConnectionPool {
    private final int max; private int active;
    public ConnectionPool(int max) { this.max = max; }
    public void setActive(int a) { this.active = a; }

    // ms spent WAITING for a connection when the pool is saturated
    public int acquireWaitMs() { return active >= max ? 2500 : 5; }
    public boolean saturated() { return active >= max; }
    public int getActive() { return active; }
    public int getMax() { return max; }
}
