package com.bank.latency;

import java.util.*;
import java.util.logging.Logger;

// Attributes total request time across the five layers (distributed-trace style).
public class LatencyTracer {
    private static final Logger log = Logger.getLogger(LatencyTracer.class.getName());

    public int trace(int cpuPct, ConnectionPool pool, DnsResolver dns, int dbQueryMs, int appComputeMs) {
        Map<String,Integer> spans = new LinkedHashMap<>();
        spans.put("app-compute", appComputeMs);
        spans.put("dns-resolve (networking)", dns.resolveMs());
        spans.put("pool-wait (app/db)", pool.acquireWaitMs());
        spans.put("db-query (downstream)", dbQueryMs);
        int total = spans.values().stream().mapToInt(Integer::intValue).sum();

        log.info(() -> "CPU=" + cpuPct + "% memory NORMAL — yet total latency=" + total + "ms");
        spans.forEach((k,v) -> log.info("  span " + k + " = " + v + "ms"));
        // Point at the biggest waiting span
        String worst = spans.entrySet().stream().max(Map.Entry.comparingByValue()).get().getKey();
        log.warning(() -> "bottleneck = '" + worst + "' (WAIT not CPU) — pool.saturated=" + pool.saturated()
                + ", dns=" + dns.resolveMs() + "ms");
        return total;
    }
}
