package com.bank.latency;

import java.math.BigDecimal;
import java.util.logging.*;

public class LatencyDemo {
    private static final Logger log = Logger.getLogger(LatencyDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        LatencyTracer tracer = new LatencyTracer();

        // SLOW: CPU 40% (normal) but pool saturated + DNS spike
        ConnectionPool pool = new ConnectionPool(10); pool.setActive(10);  // saturated
        DnsResolver dns = new DnsResolver(); dns.setLatencyMs(300);         // CoreDNS spike
        int slow = tracer.trace(40, pool, dns, 60, 40);
        log.info("slow transfer attempt total=" + slow + "ms (CPU looked fine!)");

        // FIX: enlarge pool (not saturated) + fix CoreDNS
        ConnectionPool pool2 = new ConnectionPool(30); pool2.setActive(12); // headroom
        DnsResolver dns2 = new DnsResolver(); dns2.setLatencyMs(3);          // healthy
        int fast = tracer.trace(40, pool2, dns2, 60, 40);
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("after fix: transfer SAV2001->CUR3001 Rs.50000 in " + fast + "ms SUCCESS");
    }
}
